import { WORK_SCENES } from './work-scenes.js';
const clone=value=>JSON.parse(JSON.stringify(value));
export const JOB_LABELS={title:'職務名',nextStep:'次の工程',contact:'回答窓口',changeReason:'変更理由（候補者へ公開）',followupQuestion:'追加で聞きたい1問（候補者へ公開・回答は任意）'};
const content=()=>({title:'ジュニア CS',scenes:clone(WORK_SCENES),nextStep:'具体例と候補者の質問を一緒に確認する会話。日程の調整や選考判断はこのデモでは行いません。',contact:'灯りワークス 採用担当 B（架空）。このデモ内の質問欄で回答します。',changeReason:'',followupQuestion:''});
export function createCompanyJob(){return {schema:1,published:[{version:1,publishedAt:null,content:content()}],editor:null,savedDraft:null,fieldProposal:null,fieldEditor:{reason:'',question:''},nextProposalId:1};}
export function currentJob(state){return state.companyJob.published.at(-1);}
export function jobEditor(state){return state.companyJob.editor??={baseVersion:currentJob(state).version,content:clone(currentJob(state).content),sourceProposalId:null};}
export function setJobField(state,key,value,sceneId){if(typeof value!=='string'||value.length>4000)return false;const draft=jobEditor(state);if(sceneId){const scene=draft.content.scenes.find(s=>s.id===sceneId);if(!scene||!['title','description'].includes(key))return false;scene[key]=value;}else if(Object.hasOwn(JOB_LABELS,key))draft.content[key]=value;else return false;return true;}
function validContent(c){return c&&['title','nextStep','contact'].every(k=>typeof c[k]==='string'&&c[k].trim()&&c[k].length<=4000)&&['changeReason','followupQuestion'].every(k=>typeof c[k]==='string'&&c[k].length<=4000)&&Array.isArray(c.scenes)&&c.scenes.length===3&&c.scenes.every((s,i)=>s.id===WORK_SCENES[i].id&&['title','description'].every(k=>typeof s[k]==='string'&&s[k].trim()&&s[k].length<=4000));}
function normalized(c){const result=Object.fromEntries(Object.keys(JOB_LABELS).map(k=>[k,c[k].trim()]));result.scenes=c.scenes.map(s=>({id:s.id,title:s.title.trim(),description:s.description.trim()}));return result;}
export function jobDifferences(before,after){const result=[];for(const [key,label] of Object.entries(JOB_LABELS))if(before?.[key]!==after?.[key])result.push({key,label,before:before?.[key]??'',after:after?.[key]??''});for(const scene of after?.scenes??[]){const old=before?.scenes?.find(s=>s.id===scene.id);for(const key of ['title','description'])if(old?.[key]!==scene[key])result.push({key:scene.id+'-'+key,label:'仕事の場面：'+scene.title+(key==='title'?'（見出し）':'（説明）'),before:old?.[key]??'',after:scene[key]});}return result;}
export function saveJobDraft(state){const edit=jobEditor(state);if(edit.baseVersion!==currentJob(state).version||!validContent(edit.content))return {ok:false,reason:'職務名・3つの場面・次の工程・回答窓口を確認してください。'};state.companyJob.savedDraft=clone({...edit,content:normalized(edit.content)});state.companyJob.editor=clone(state.companyJob.savedDraft);return {ok:true};}
export function previewJob(state){const draft=state.companyJob.savedDraft;if(!draft||draft.baseVersion!==currentJob(state).version||JSON.stringify(draft)!==JSON.stringify(state.companyJob.editor))return {ok:false,reason:'編集した内容を下書き保存してからプレビューしてください。'};if(!jobDifferences(currentJob(state).content,draft.content).length)return {ok:false,reason:'公開中の説明と同じです。変更を入力してください。'};if(!draft.content.changeReason.trim())return {ok:false,reason:'候補者に伝える変更理由を入力してください。'};return {ok:true,preview:{baseVersion:draft.baseVersion,version:draft.baseVersion+1,content:clone(draft.content),sourceProposalId:draft.sourceProposalId}};}
export function publishJob(state,preview,now=new Date().toISOString()){const fresh=previewJob(state);if(!fresh.ok||JSON.stringify(fresh.preview)!==JSON.stringify(preview))return {ok:false,reason:'プレビュー後に下書きか公開版が変わりました。保存とプレビューをやり直してください。'};const entry={version:preview.version,publishedAt:now,content:clone(preview.content)};state.companyJob.published.push(entry);if(state.companyJob.fieldProposal?.id===preview.sourceProposalId)state.companyJob.fieldProposal.reviewedAt=now;state.companyJob.editor=null;state.companyJob.savedDraft=null;return {ok:true,entry:clone(entry)};}
export function saveFieldProposal(state){const edit=state.companyJob.fieldEditor;if(!['reason','question'].every(k=>typeof edit[k]==='string'&&edit[k].trim()&&edit[k].length<=4000))return false;state.companyJob.fieldProposal={id:state.companyJob.nextProposalId++,baseVersion:currentJob(state).version,reason:edit.reason.trim(),question:edit.question.trim(),reviewedAt:null};return true;}
export function applyFieldProposal(state){const p=state.companyJob.fieldProposal;if(!p||p.baseVersion!==currentJob(state).version)return false;const draft=jobEditor(state);draft.content.changeReason=p.reason;draft.content.followupQuestion=p.question;draft.sourceProposalId=p.id;return true;}
export function candidateJobProjection(state){const job=currentJob(state);return {version:job.version,publishedAt:job.publishedAt,content:normalized(job.content)};}
export function captureSubmissionJob(state,version){state.submissionJobSnapshots??={};if(!state.submissionJobSnapshots[version])state.submissionJobSnapshots[version]=candidateJobProjection(state);}
export function submissionJob(state,version){return state.submissionJobSnapshots?.[version]??null;}
export function chooseJobResponse(state,choice){if(!['continue','add','question'].includes(choice)||!state.submissions.length)return false;state.jobResponses??={};state.jobResponses[currentJob(state).version]={choice,sourceSubmissionVersion:state.submissions.at(-1).version};return true;}
export function migrateJobSettings(state){state.companyJob??=createCompanyJob();state.submissionJobSnapshots??={};state.jobResponses??={};for(const entry of state.submissions){if(!state.submissionJobSnapshots[entry.version])state.submissionJobSnapshots[entry.version]={version:0,publishedAt:null,legacy:true,legacyScenario:entry.scenario,content:{...content(),nextStep:'旧デモでは説明を保存していませんでした。',contact:'旧デモでは説明を保存していませんでした。',changeReason:'',followupQuestion:''}};} }
function validEditableContent(c){return c&&Object.keys(JOB_LABELS).every(k=>typeof c[k]==='string'&&c[k].length<=4000)&&Array.isArray(c.scenes)&&c.scenes.length===3&&c.scenes.every((s,i)=>s.id===WORK_SCENES[i].id&&['title','description'].every(k=>typeof s[k]==='string'&&s[k].length<=4000));}
export function validJobSettings(state){const j=state.companyJob;if(j?.schema!==1||!Array.isArray(j.published)||!j.published.length||!j.published.every((p,i)=>p.version===i+1&&validContent(p.content))||!Number.isInteger(j.nextProposalId)||!j.fieldEditor||!['reason','question'].every(k=>typeof j.fieldEditor[k]==='string'&&j.fieldEditor[k].length<=4000))return false;if(!state.submissionJobSnapshots||!state.jobResponses)return false;for(const p of Object.values(state.submissionJobSnapshots))if(!Number.isInteger(p.version)||!validContent(p.content))return false;for(const d of [j.editor,j.savedDraft])if(d&&(!Number.isInteger(d.baseVersion)||!validEditableContent(d.content)))return false;const p=j.fieldProposal;if(p&&(!Number.isInteger(p.id)||!Number.isInteger(p.baseVersion)||!['reason','question'].every(k=>typeof p[k]==='string'&&p[k].length<=4000)))return false;return Object.values(state.jobResponses).every(r=>r&&['continue','add','question'].includes(r.choice)&&Number.isInteger(r.sourceSubmissionVersion));}
